 test("zero_record_generation_requires_explicit_close_never_signed_credit",()->{try(Fixture f=new Fixture();JournalGuard17.Scope lock=f.lock()){JournalRegistry17 r=f.reg();f.enroll(r);archive(f,r,f.originals);generation(f,r,9);List<JournalRegistry17.Original> unused=Arrays.asList(new JournalRegistry17.Original(g(9),MAGIC.length,sha(MAGIC),"UNUSED",h("cold-empty")));fails(()->r.beginArchive(h("notclosed"),r.inspect(null,false).head,unused),"header-only newgeneration not automaticallyclosed");r.closeGeneration(g(9),0,MAGIC.length,ZERO,true,false);JournalRegistry17.Snapshot s=r.inspect(null,false);ok(s.reservedRecords==0&&s.committedRecords==0&&!s.pending,"zero closed records not signedinput credit");archive(f,r,unused);generation(f,r,10);r.closeGeneration(g(10),0,MAGIC.length,ZERO,false,false);List<JournalRegistry17.Original> forged=Arrays.asList(new JournalRegistry17.Original(g(10),MAGIC.length,sha(MAGIC),"UNUSED",h("forgedempty")));fails(()->r.beginArchive(h("failedclose"),r.inspect(null,false).head,forged),"failed zero-recordclose stays unresolved");JournalRegistry17 fresh=f.reg();s=fresh.inspect(null,false);ok(s.reservedGenerations==10&&s.committedGenerations==10&&s.committedRecords==0,"restart preserves zerorecord counters withoutauthority");}});

 test("initial_request_credit_before_nonce_blocks_input_until_real_receipt",()->{try(Fixture f=new Fixture();JournalGuard17.Scope lock=f.lock()){JournalRegistry17 r=f.reg();JournalRegistry17.Snapshot s=r.enroll(f.originals,h("backup"),h("receiver"),h("cold"),"ROOT");ok(s.reservedRequests==1&&s.committedReceipts==0&&s.pending,"implicit accepted request already charged");fails(()->r.inspect(null,false),"unbound first credit blocks startup");fails(()->r.reserveRequest(g(400),"PREVIEW"),"first credit requires APPLY");JournalRegistry17.RequestTicket t=r.reserveRequest(g(400),"APPLY");s=r.inspect(null,true);ok(s.reservedRequests==1&&s.committedReceipts==0&&s.pending,"binding never charges twice or refunds");fails(()->r.reserveRequest(g(401),"RECOVER"),"unknown first request blocks new identity");String relative="product-input-lifecycle17/request-"+g(400)+".json";byte[] receipt="{\"status\":\"FAILED_CLOSED_NO_AUTHORITY\",\"mockOnly\":true}".getBytes();put(new File(f.root,relative),receipt);r.commitRequest(t,relative,receipt.length,sha(receipt));s=r.inspect(null,false);ok(s.reservedRequests==1&&s.committedReceipts==1&&!s.pending,"failed operation receipt still consumes credit");}});
 test("request32_monotonic_missing_mutated_receipt_no_refund",()->{try(Fixture f=new Fixture();JournalGuard17.Scope lock=f.lock()){JournalRegistry17 r=f.reg();f.enroll(r);for(int i=2;i<=32;i++){String nonce=g(500+i),relative="product-input-lifecycle17/request-"+nonce+".json";JournalRegistry17.RequestTicket t=r.reserveRequest(nonce,"PREVIEW");byte[] b=("{\"mockOnly\":true,\"n\":"+i+"}").getBytes();put(new File(f.root,relative),b);r.commitRequest(t,relative,b.length,sha(b));r.commitRequest(t,relative,b.length,sha(b));}JournalRegistry17.Snapshot s=r.inspect(null,false);ok(s.reservedRequests==32&&s.committedReceipts==32,"global original32 request credits consumed");byte[] before=Files.readAllBytes(f.index().toPath());fails(()->r.reserveRequest(g(600),"APPLY"),"33rd request");ok(Arrays.equals(before,Files.readAllBytes(f.index().toPath())),"no extra record at32 ceiling");File receipt=new File(f.root,"product-input-lifecycle17/request-"+g(502)+".json");byte[] body=Files.readAllBytes(receipt.toPath());Files.delete(receipt.toPath());fails(()->f.reg().inspect(null,true),"missing committed receipt does not recount/refund");fails(()->r.reserveRequest(g(601),"APPLY"),"missing receipt cannot free credit");put(receipt,body);byte[] corrupt=body.clone();corrupt[0]^=1;put(receipt,corrupt);final String known=s.head;fails(()->f.reg().inspect(known,true),"receipt exact SHA changed");put(receipt,body);s=f.reg().inspect(known,false);ok(s.reservedRequests==32&&s.committedReceipts==32,"same-byte explicit fixture restoration preserves counters");}});
