 test("request_intent_receipt_cutpoints_preserve_highwater",()->{for(String type:new String[]{"REQUEST_RESERVE","REQUEST_RECEIPT"})for(String stage:new String[]{"registry-before-append:","registry-before-write:","registry-after-write:","registry-after-filesync:","registry-after-dirsync:"})try(Fixture f=new Fixture();JournalGuard17.Scope lock=f.lock()){JournalRegistry17 r=f.reg();f.enroll(r);String nonce=g(800),relative="product-input-lifecycle17/request-"+nonce+".json";byte[] b="{\"mockOnly\":true}".getBytes();JournalRegistry17.RequestTicket t=null;if(type.equals("REQUEST_RECEIPT")){t=r.reserveRequest(nonce,"PREVIEW");put(new File(f.root,relative),b);}f.cut.cut=stage+type;final JournalRegistry17.RequestTicket ticket=t;fails(()->{if(type.equals("REQUEST_RESERVE"))r.reserveRequest(nonce,"PREVIEW");else r.commitRequest(ticket,relative,b.length,sha(b));},"request cut "+stage+type);f.cut.cut=null;JournalRegistry17.Snapshot s=f.reg().inspect(null,true);boolean written=stage.contains("after-");if(type.equals("REQUEST_RESERVE"))ok(s.reservedRequests==(written?2:1)&&s.committedReceipts==1&&s.pending==written,"reservation survives after bytes withoutrefund");else ok(s.reservedRequests==2&&s.committedReceipts==(written?2:1),"receipt result never refunds reservation");}});
 test("faults_each_index_generation_intent_state",()->{for(String point:new String[]{"registry-before-append:GEN_BEGIN","registry-before-write:GEN_BEGIN","registry-after-write:GEN_BEGIN","registry-after-filesync:GEN_BEGIN","registry-after-dirsync:GEN_BEGIN"})try(Fixture f=new Fixture();JournalGuard17.Scope lock=f.lock()){JournalRegistry17 r=f.reg();f.enroll(r);archive(f,r,f.originals);f.cut.cut=point;fails(()->r.beginGeneration(g(9)),"cut "+point);f.cut.cut=null;JournalRegistry17 fresh=f.reg();JournalRegistry17.Snapshot s=fresh.inspect(null,true);boolean effect=point.contains("after-");ok(s.pending==effect&&s.reservedGenerations==(effect?9:8),"uncertain intent charged according retained bytes "+point);if(effect)fails(()->fresh.beginGeneration(g(10)),"no refund/replay after "+point);}});
 test("torn_index_append_poisoned_and_never_refunded",()->{try(Fixture f=new Fixture();JournalGuard17.Scope lock=f.lock()){JournalRegistry17 r=f.reg();f.enroll(r);archive(f,r,f.originals);f.boundary=new JournalGuard17.Boundary(){@Override public FileOutputStream append(File p)throws IOException{regular(p);return new FileOutputStream(p,true){@Override public void write(byte[] b)throws IOException{super.write(b,0,b.length/2);getFD().sync();throw new IOException("injected partial write");}};}};r=f.reg();final JournalRegistry17 selected=r;fails(()->selected.beginGeneration(g(9)),"torn append");fails(()->f.reg().inspect(null,true),"torn registry refuses inspection");}});
 test("cross_instance_lock_and_stale_ticket",()->{try(Fixture f=new Fixture()){JournalRegistry17.Ticket[] t={null};try(JournalGuard17.Scope lock=f.lock()){JournalRegistry17 r=f.reg();f.enroll(r);archive(f,r,f.originals);t[0]=r.beginGeneration(g(9));final IOException[] error={null};Thread other=new Thread(()->{try(JournalGuard17.Scope denied=JournalGuard17.enter(f.root,f.boundary,Registry17Test::sync,0)){throw new AssertionError("interleaved lock admitted");}catch(IOException e){error[0]=e;}});other.start();other.join(1000);ok(!other.isAlive()&&error[0]!=null&&error[0].getMessage().contains("100MS"),"cross instance100ms guard");Process probe=new ProcessBuilder(System.getProperty("java.home")+"/bin/java","-Xmx64m","-cp",System.getProperty("java.class.path"),"vn.rtr.aeris.mission.Registry17Test","--lock-probe",f.root.getAbsolutePath()).redirectErrorStream(true).start();ok(probe.waitFor(3,java.util.concurrent.TimeUnit.SECONDS),"separate JVM lock probe bounded");byte[] probeOut=probe.getInputStream().readAllBytes();ok(probeOut.length<2048&&probe.exitValue()==0&&new String(probeOut,StandardCharsets.US_ASCII).startsWith("DENIED:"),"other JVM remains blocked after same-JVM timeout");JournalRegistry17 fresh=f.reg();fails(()->fresh.beginGeneration(g(10)),"pending no interleave");put(new File(f.root,"product-input01/"+g(9)+".aj02"),MAGIC);fresh.commitGeneration(t[0],MAGIC.length,ZERO);fresh.commitGeneration(t[0],MAGIC.length,ZERO);ok(fresh.inspect(null,false).committedGenerations==9,"same ticket observed commit not rerun");}}});

 test("faults_enrollment_generation_append_archive_commit",()->{String[] types={"ENROLL_BEGIN","ENROLL_COMMIT","GEN_COMMIT","APPEND_BEGIN","APPEND_COMMIT","ARCHIVE_BEGIN","ARCHIVE_COMMIT"};String[] stages={"registry-before-append:","registry-before-write:","registry-after-write:","registry-after-filesync:","registry-after-dirsync:"};for(String type:types)for(String stage:stages)try(Fixture f=new Fixture();JournalGuard17.Scope lock=f.lock()){JournalRegistry17 r=f.reg();String baseline=null;JournalRegistry17.Ticket t=null;File target=null;byte[] next=null;String relative=null;if(!type.startsWith("ENROLL")){baseline=f.enroll(r).head;if(type.startsWith("ARCHIVE")){byte[] plan=plan(baseline,f.originals);if(type.equals("ARCHIVE_COMMIT")){t=r.beginArchive(sha(plan),baseline,f.originals);relative=moveArchive(f,plan,f.originals);}}else{archive(f,r,f.originals);if(type.equals("GEN_COMMIT")){t=r.beginGeneration(g(9));put(new File(f.root,"product-input01/"+g(9)+".aj02"),MAGIC);}else{generation(f,r,9);target=new File(f.root,"product-input01/"+g(9)+".aj02");next=row(1,10,1,ZERO,"intent".getBytes());if(type.equals("APPEND_COMMIT")){t=r.beginAppend(g(9),1,MAGIC.length,MAGIC.length+next.length,sha(next),tail(next));add(target,next);}}}}f.cut.cut=stage+type;final JournalRegistry17.Ticket ticket=t;final String moved=relative;final byte[] append=next;final String oldHead=baseline;fails(()->{if(type.startsWith("ENROLL"))f.enroll(r);else if(type.equals("GEN_COMMIT"))r.commitGeneration(ticket,MAGIC.length,ZERO);else if(type.equals("APPEND_BEGIN"))r.beginAppend(g(9),1,MAGIC.length,MAGIC.length+append.length,sha(append),tail(append));else if(type.equals("APPEND_COMMIT"))r.commitAppend(ticket);else if(type.equals("ARCHIVE_BEGIN"))r.beginArchive(sha(plan(oldHead,f.originals)),oldHead,f.originals);else r.commitArchive(ticket,moved);},"cut "+stage+type);f.cut.cut=null;try{JournalRegistry17.Snapshot after=f.reg().inspect(null,true);ok(after.reservedGenerations>=after.committedGenerations&&after.reservedRecords>=after.committedRecords&&after.reservedArchives>=after.committedArchives,"monotonic retained highwater "+type);if(type.startsWith("APPEND"))ok(after.reservedRecords==1||stage.contains("before-")&&type.equals("APPEND_BEGIN")&&after.reservedRecords==0,"unknown append never refunded");}catch(IOException refused){ok(type.startsWith("ENROLL")||refused.getMessage().contains("PENDING")||refused.getMessage().contains("INDEX"),"partial safely refused "+type);}for(int i=1;i<=8;i++){File a=new File(f.root,"product-input01/"+g(i)+".aj02");if(!a.exists()){File[] batches=new File(f.root,"product-input-archives17").listFiles();for(File b:batches)if(new File(b,a.getName()).exists())a=new File(b,a.getName());}ok(Arrays.equals(Files.readAllBytes(a.toPath()),MAGIC),"original retained across fault "+type);}}});
 test("hot_append_io_timing_no_archived_original_reads",()->{try(Fixture f=new Fixture();JournalGuard17.Scope lock=f.lock()){JournalRegistry17 r=f.reg();f.enroll(r);archive(f,r,f.originals);generation(f,r,9);final long[] archiveRead={0};f.boundary=new JournalGuard17.Boundary(){@Override public byte[] readRange(File p,long at,int n,int max)throws IOException{if(p.getPath().contains("product-input-archives17"))archiveRead[0]+=n;return super.readRange(p,at,n,max);}};r=f.reg();r.inspect(null,false);archiveRead[0]=0;File target=new File(f.root,"product-input01/"+g(9)+".aj02");String head=ZERO;long maximum=0,total=0;for(int i=1;i<=100;i++){byte[] next=row(i,10+i,i%2==1?1:2,head,(i%2==1?"intent":"200").getBytes());long start=System.nanoTime();JournalRegistry17.Ticket t=r.beginAppend(g(9),i,target.length(),target.length()+next.length,sha(next),tail(next));add(target,next);r.commitAppend(t);long elapsed=System.nanoTime()-start;maximum=Math.max(maximum,elapsed);total+=elapsed;head=tail(next);}ok(archiveRead[0]==0,"no archived bytes read in hot path");ok(maximum<200000000L,"mock host append path200ms guard budget");System.out.println("TIMING hostJVM100Appends maxNs="+maximum+" meanNs="+(total/100)+" archivedBytesRead="+archiveRead[0]+" actualArchiveCorpusBytes="+(8*MAGIC.length)+" full64MiBCorpusNotRun=true AndroidLatencyNotClaimed=true");}});
